(function(root,factory){const engine=typeof module==='object'&&module.exports?require('./society-next'):root.SocietyNext;const api=factory(engine);if(typeof module==='object'&&module.exports)module.exports=api;else root.SocietyExperiments=api})(globalThis,(engine)=>{const {World}=engine;

const CASES=[{name:'Taste only',socialFashion:false},{name:'Social fashion'},{name:'No groups',groups:false},{name:'No price pacts',coordination:false},{name:'Hidden market insight',oracle:true},{name:'Food shortage',scarcity:true}];
function run({seeds=[11,42,73,104],count=12,minutes=1440}={},progress=()=>{}){const start=Date.now(),runs=[],stories=[];for(const config of CASES)for(const seed of seeds){const w=new World({...config,seed,count});let last=0;const milestones=[];for(let i=0;i<minutes;i++){w.tick();for(const e of w.s.events){const id=Number(e.id.slice(1));if(id<=last)continue;if(['group','supply','exit','settlement','trade','insight','advice'].includes(e.type)&&milestones.length<100&&(e.type!=='trade'||milestones.filter(m=>m.type==='trade').length<8))milestones.push(JSON.parse(JSON.stringify(e)))}last=Number(w.s.events.at(-1).id.slice(1));if(i%120===0)w.validate()}w.validate();runs.push({case:config.name,seed,...w.metrics(),bytes:JSON.stringify(w.snapshot()).length});if(seed===seeds[0])stories.push({case:config.name,seed,events:milestones});progress({done:runs.length,total:CASES.length*seeds.length})}
const keys=['hatTrades','inputTrades','hunger','foodGini','workshops','suppliesCreated','exits','revelations','advice','conflicts','pricePacts','friendColorSimilarity','colorDiversity'];const summary=CASES.map(c=>{const rows=runs.filter(r=>r.case===c.name),mean={},range={};for(const k of keys){const values=rows.map(r=>r[k]).filter(v=>v!==null&&Number.isFinite(v));mean[k]=values.length?values.reduce((s,v)=>s+v,0)/values.length:null;range[k]=values.length?[Math.min(...values),Math.max(...values)]:null}return{name:c.name,mean,range}});return{engineVersion:2,seeds,count,minutes,durationMs:Date.now()-start,summary,runs,stories}}
return{CASES,run};
});
